Ecm_Vtacho_Evt ecm_vtacho_looping( void )
{	
	Ecm_Vtacho_Evt	evt =  ECM_VTACHO_EVT_NULL ;

	os_res_request( ecm_vtacho_vars.res , 0 );
	{
		if( ecm_vtacho_vars.state )
		{
			evt = (ecm_vtacho_vars.state)();
		}
	}
	os_res_release( ecm_vtacho_vars.res );

	return evt ;
}

